from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts divisible by k."""
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))

        @lru_cache(maxsize=None)
        def visit(pos: int, balance: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                next_started = started or digit != 0
                next_balance = balance
                next_remainder = remainder
                if next_started:
                    next_balance += 1 if digit % 2 == 0 else -1
                    next_remainder = (remainder * 10 + digit) % k
                total += visit(
                    pos + 1, next_balance, next_remainder,
                    next_started, next_tight
                )
            return total

        return visit(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0:
        return False
    tile_list = list(tiles[:n])
    usable = []
    for a, b in tile_list:
        if a <= 0 or b <= 0:
            continue
        orientations = {(a, b), (b, a)}
        placements = []
        for th, tw in orientations:
            if th > h or tw > w:
                continue
            for r in range(h - th + 1):
                for c in range(w - tw + 1):
                    mask = 0
                    row_bits = ((1 << tw) - 1) << c
                    for rr in range(r, r + th):
                        mask |= row_bits << (rr * w)
                    placements.append((r * w + c, mask))
        if placements:
            usable.append((a * b, placements))

    full = (1 << (h * w)) - 1
    if sum(area for area, _ in usable) < h * w:
        return False

    # The state records which available tiles have been used and the occupied
    # cells. Tiles with equal dimensions remain distinct, as they are distinct
    # physical tiles in the input.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining_area = h * w - occupied.bit_count()
        available_area = sum(
            area for i, (area, _) in enumerate(usable) if not (used >> i) & 1
        )
        if available_area < remaining_area:
            return False

        empty = full ^ occupied
        lowest = empty & -empty
        pos = lowest.bit_length() - 1
        row, col = divmod(pos, w)

        # Try larger tiles first to reduce branching on typical instances.
        for i, (_, placements) in sorted(
            enumerate(usable),
            key=lambda item: -item[1][0],
        ):
            if (used >> i) & 1:
                continue
            for anchor, mask in placements:
                if anchor == pos and not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

