def count_power_representations(n: int) -> int:
    """ Count integers x in [1, n] expressible as a^b for positive a and b >= 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The number of such integers.
    """
    # Integer kth root, avoiding floating-point rounding at the upper bound.
    def root(value: int, exponent: int) -> int:
        lo, hi = 1, 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            power = mid ** exponent
            if power <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    limit = n.bit_length()
    mu = [1] * (limit + 1)
    primes = []
    composite = [False] * (limit + 1)
    for i in range(2, limit + 1):
        if not composite[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > limit:
                break
            composite[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            mu[i * p] = -mu[i]

    def primitive_count(x: int) -> int:
        # Count integers >= 2 that are not themselves nontrivial powers.
        return sum(mu[k] * (root(x, k) - 1)
                   for k in range(1, limit + 1) if mu[k])

    # Each perfect power greater than one has a unique primitive root and
    # maximal exponent. Group by that exponent.
    answer = 1  # the number 1
    for exponent in range(2, limit + 1):
        x = root(n, exponent)
        if x >= 2:
            answer += primitive_count(x)
    return answer

from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _square_digit_signatures(n: int) -> dict[str, int]:
    """Count n-digit squares by their digit multisets."""
    first = isqrt(10 ** (n - 1) - 1) + 1
    last = isqrt(10 ** n - 1)
    counts: dict[str, int] = {}
    for root in range(first, last + 1):
        signature = "".join(sorted(str(root * root)))
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Given digits s, count the unique square numbers that use those digits.

    Only squares with exactly n decimal digits are considered. Each such square
    is counted once, even if more than one digit ordering can produce it.
    """
    return _square_digit_signatures(n).get("".join(sorted(s)), 0)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper pattern."""
    def corner(x: float, y: float) -> float:
        # Signed area (black +1, white -1) in [0,x] x [0,y], with x,y in [0,2].
        if x == 0 or y == 0:
            return 0.0

        def slice_area(v: float) -> float:
            # Along a horizontal slice, color changes at x=1 and x=2-v.
            # The value at v=2 is interpreted as its left-hand limit.
            if v >= 2:
                return -x
            cuts = [0.0, x]
            for z in (1.0, 2.0 - v):
                if 0.0 < z < x:
                    cuts.append(z)
            cuts.sort()
            total = 0.0
            for lo, hi in zip(cuts, cuts[1:]):
                mid = (lo + hi) / 2.0
                sign = -1.0 if (int(mid) + int((mid + v) // 2)) % 2 else 1.0
                total += (hi - lo) * sign
            return total

        breaks = sorted({0.0, y, *[z for z in (1.0, 2.0 - x) if 0.0 < z < y]})
        return sum((b - a) * (slice_area(a) + slice_area(b)) / 2.0
                   for a, b in zip(breaks, breaks[1:]))

    def prefix(x: int, y: int) -> float:
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 2)
        return qx * corner(2.0, ry) + qy * corner(float(rx), 2.0) + corner(float(rx), float(ry))

    signed = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    area = (C - A) * (D - B)
    return int(round(area + signed))

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in the range that end with s and use digits <= limit."""
    suffix_value = int(s)
    suffix_length = len(s)

    if any(int(digit) > limit for digit in s):
        return 0

    def count_up_to(bound: int) -> int:
        if bound < suffix_value:
            return 0

        max_prefix = (bound - suffix_value) // (10 ** suffix_length)
        digits = str(max_prefix)

        # Prefix zero is valid, and represents s itself.
        total = 1
        for length in range(1, len(digits)):
            total += limit * (limit + 1) ** (length - 1)

        prefix_count = 0
        for i, char in enumerate(digits):
            current = int(char)
            remaining = len(digits) - i - 1
            if i == 0:
                prefix_count += max(0, min(current - 1, limit)) * (limit + 1) ** remaining
            else:
                prefix_count += min(current, limit + 1) * (limit + 1) ** remaining
            if current > limit:
                break
            if i == len(digits) - 1:
                prefix_count += 1
        return total + prefix_count

    return count_up_to(finish) - count_up_to(start - 1)

from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified 3x3 tic-tac-toe game described in the problem."""
    values = tuple(value for row in grid for value in row)
    lines = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    full = (1 << 9) - 1

    @lru_cache(maxsize=None)
    def solve(takahashi: int, aoki: int, turn: int, score_difference: int) -> bool:
        """Return whether Takahashi wins with optimal play from this position."""
        for line in lines:
            if takahashi & line == line:
                return True
            if aoki & line == line:
                return False

        occupied = takahashi | aoki
        if occupied == full:
            return score_difference > 0

        if turn == 0:
            # Takahashi chooses a move that makes the eventual result a win if possible.
            for cell in range(9):
                bit = 1 << cell
                if not occupied & bit:
                    if solve(takahashi | bit, aoki, 1, score_difference + values[cell]):
                        return True
            return False

        # Aoki chooses a move that makes the eventual result a loss for Takahashi if possible.
        for cell in range(9):
            bit = 1 << cell
            if not occupied & bit:
                if not solve(takahashi, aoki | bit, 0, score_difference - values[cell]):
                    return False
        return True

    return "Takahashi" if solve(0, 0, 0, 0) else "Aoki"

from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _square_digit_signatures(n: int) -> dict[str, int]:
    """Count square values below 10**n by their n-digit padded multisets."""
    last = isqrt(10 ** n - 1)
    counts: dict[str, int] = {}
    for root in range(last + 1):
        signature = "".join(sorted(str(root * root).zfill(n)))
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Count unique square values whose n-digit representation uses s's digits.

    Leading zeroes in the square representation are allowed.
    """
    return _square_digit_signatures(n).get("".join(sorted(s)), 0)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in the range that end with s and use digits <= limit."""
    suffix_value = int(s)
    suffix_length = len(s)

    if any(int(digit) > limit for digit in s):
        return 0

    def count_up_to(bound: int) -> int:
        if bound < suffix_value:
            return 0

        max_prefix = (bound - suffix_value) // (10 ** suffix_length)
        digits = str(max_prefix)
        total = 1  # Prefix zero represents s itself.

        for length in range(1, len(digits)):
            total += limit * (limit + 1) ** (length - 1)

        prefix_count = 0
        for i, char in enumerate(digits):
            current = int(char)
            remaining = len(digits) - i - 1
            if i == 0:
                prefix_count += max(0, min(current - 1, limit)) * (limit + 1) ** remaining
            else:
                prefix_count += min(current, limit + 1) * (limit + 1) ** remaining
            if current > limit:
                break
            if i == len(digits) - 1 and max_prefix > 0:
                prefix_count += 1
        return total + prefix_count

    return count_up_to(finish) - count_up_to(start - 1)

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to cover the required section lengths with bounded sensors."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # Enumerate per-section feasible combinations and combine them while
    # respecting the shared sensor inventory.
    options = []
    for demand in sections[:n]:
        section = []
        max_a = min(k1, (demand + l1 - 1) // l1)
        for a in range(max_a + 1):
            remaining = max(0, demand - a * l1)
            b = (remaining + l2 - 1) // l2
            if b <= k2:
                section.append((a, b, a * c1 + b * c2))
        # For each usage count of type 1 only the smallest sufficient type 2
        # count was considered, which is enough since costs are nonnegative.
        options.append(section)

    # Sparse dynamic programming over the counts actually used.
    dp = {(0, 0): 0}
    for section in options:
        if not section:
            return -1
        nxt = {}
        for (used1, used2), cost in dp.items():
            for a, b, price in section:
                x, y = used1 + a, used2 + b
                if x <= k1 and y <= k2:
                    key = (x, y)
                    value = cost + price
                    if value < nxt.get(key, float("inf")):
                        nxt[key] = value
        dp = nxt
        if not dp:
            return -1
    return min(dp.values()) if dp else -1

