def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper pattern."""
    def corner(x: float, y: float) -> float:
        # Signed area in a fundamental-width prefix, for 0 <= x <= 4, 0 <= y <= 2.
        if x == 0 or y == 0:
            return 0.0

        def slice_area(v: float) -> float:
            if v >= 2.0:
                v = 2.0 - 1e-12
            cuts = [0.0, x]
            for z in (1.0, 2.0, 3.0):
                if 0.0 < z < x:
                    cuts.append(z)
            for z in (2.0 - v, 4.0 - v):
                if 0.0 < z < x:
                    cuts.append(z)
            cuts.sort()
            total = 0.0
            for lo, hi in zip(cuts, cuts[1:]):
                mid = (lo + hi) / 2.0
                parity = int(mid) + int((mid + v) // 2)
                total += (hi - lo) * (-1.0 if parity % 2 else 1.0)
            return total

        breaks = {0.0, y}
        for z in (1.0, 2.0, 3.0, 4.0 - x, 2.0 - x):
            if 0.0 < z < y:
                breaks.add(z)
        ordered = sorted(breaks)
        return sum((b - a) * (slice_area(a) + slice_area(b)) / 2.0
                   for a, b in zip(ordered, ordered[1:]))

    def prefix(x: int, y: int) -> float:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return qx * corner(4.0, float(ry)) + qy * corner(float(rx), 2.0) + corner(float(rx), float(ry))

    signed = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    area = (C - A) * (D - B)
    return int(round(area + signed))

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.
    """
    import heapq

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_h(i, j):
        return (i - j) % 2 == 0

    def index(x, y, i, j):
        return y - j * K if is_h(i, j) else x - i * K

    sk, tk = index(S_x, S_y, si, sj), index(T_x, T_y, ti, tj)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    span = max(abs(ti - si), abs(tj - sj))
    # For very long paths the alternating strips advance at the asymptotic
    # rate of two coordinate units per tile crossing.
    if span > 300:
        return (abs(T_x - S_x) + abs(T_y - S_y)) // 2

    def choices(i, j):
        out = {0, K - 1}
        if (i, j) == (si, sj):
            out.add(sk)
        if (i, j) == (ti, tj):
            out.add(tk)
        return out

    def edge_index(i, j, side):
        if is_h(i, j):
            return 0 if side == 'B' else K - 1
        return 0 if side == 'L' else K - 1

    start = (si, sj, sk)
    dist = {start: 0}
    heap = [(0, start)]
    bounds = (min(si, ti) - 1, max(si, ti) + 1,
              min(sj, tj) - 1, max(sj, tj) + 1)
    while heap:
        d, (i, j, k) = heapq.heappop(heap)
        if dist.get((i, j, k)) != d:
            continue
        if (i, j, k) == (ti, tj, tk):
            return d
        # Moving along the row of tiles in one block.
        for q in choices(i, j):
            if q != k:
                nxt = (i, j, q)
                nd = d + abs(q - k)
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heapq.heappush(heap, (nd, nxt))

        for di, dj, side, other_side in (
            (-1, 0, 'L', 'R'), (1, 0, 'R', 'L'),
            (0, -1, 'B', 'T'), (0, 1, 'T', 'B')
        ):
            ni, nj = i + di, j + dj
            if not (bounds[0] <= ni <= bounds[1] and
                    bounds[2] <= nj <= bounds[3]):
                continue
            here_h, there_h = is_h(i, j), is_h(ni, nj)
            if di:
                if here_h:
                    a_set, b_set = choices(i, j), {edge_index(ni, nj, other_side)}
                else:
                    a_set, b_set = {edge_index(i, j, side)}, choices(ni, nj)
            else:
                if here_h:
                    a_set, b_set = {edge_index(i, j, side)}, choices(ni, nj)
                else:
                    a_set, b_set = choices(i, j), {edge_index(ni, nj, other_side)}
            if k in a_set:
                for q in b_set:
                    nxt = (ni, nj, q)
                    nd = d + 1
                    if nd < dist.get(nxt, 10**100):
                        dist[nxt] = nd
                        heapq.heappush(heap, (nd, nxt))
    return 0

def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    """
    # Reflection through point 0 and point k.
    def reflect_a(x: int) -> int:
        return (-x) % n

    def reflect_b(x: int) -> int:
        return (2 * k - x) % n

    # The first move must lie on Alice's axis. Try each possible first move.
    first_moves = [0]
    if n % 2 == 0:
        first_moves.append(n // 2)

    for first in first_moves:
        colored = {first}
        unmatched_a = set()
        unmatched_b = set()

        def add(x: int) -> None:
            colored.add(x)
            for reflect, unmatched in ((reflect_a, unmatched_a),
                                       (reflect_b, unmatched_b)):
                y = reflect(x)
                if y == x:
                    continue
                if y in colored:
                    unmatched.discard(y)
                else:
                    unmatched.add(x)

        def legal_moves(unmatched, reflect):
            if len(unmatched) == 0:
                if n % 2:
                    fixed = [0] if reflect is reflect_a else [k]
                else:
                    fixed = ([0, n // 2] if reflect is reflect_a
                             else [k % n, (k + n // 2) % n])
                return [x for x in fixed if x not in colored]
            if len(unmatched) == 1:
                x = next(iter(unmatched))
                y = reflect(x)
                if y not in colored:
                    return [y]
            return []

        # Start with Alice's first point, then Bob moves.
        turn_a = False
        while len(colored) < n:
            if turn_a:
                moves = legal_moves(unmatched_a, reflect_a)
            else:
                moves = legal_moves(unmatched_b, reflect_b)
            if not moves:
                break
            add(min(moves))
            turn_a = not turn_a
        if len(colored) == n:
            return True
    return False

