from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _square_digit_signatures(n: int) -> dict[str, int]:
    """Count squares with at most one leading zero in an n-digit representation."""
    first = 0 if n == 1 else isqrt(10 ** (n - 2) - 1) + 1
    last = isqrt(10 ** n - 1)
    counts: dict[str, int] = {}
    for root in range(first, last + 1):
        signature = "".join(sorted(str(root * root).zfill(n)))
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Count unique squares whose digits can be arranged to match s."""
    return _square_digit_signatures(n).get("".join(sorted(s)), 0)

