def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    """
    def reflect_a(x: int) -> int:
        return (-x) % n

    def reflect_b(x: int) -> int:
        return (2 * k - x) % n

    first_moves = [0]
    if n % 2 == 0:
        first_moves.append(n // 2)

    for first in first_moves:
        colored = set()
        unmatched_a = set()
        unmatched_b = set()

        def add(x: int) -> None:
            colored.add(x)
            for reflect, unmatched in ((reflect_a, unmatched_a),
                                       (reflect_b, unmatched_b)):
                y = reflect(x)
                if y == x:
                    continue
                if y in colored:
                    unmatched.discard(y)
                else:
                    unmatched.add(x)

        def legal_moves(unmatched, reflect):
            if len(unmatched) == 0:
                if reflect is reflect_a:
                    fixed = [0] if n % 2 else [0, n // 2]
                else:
                    fixed = [k % n] if n % 2 else [k % n, (k + n // 2) % n]
                return [x for x in fixed if x not in colored]
            if len(unmatched) == 1:
                x = next(iter(unmatched))
                y = reflect(x)
                if y not in colored:
                    return [y]
            return []

        add(first)
        turn_a = False
        while len(colored) < n:
            if turn_a:
                moves = legal_moves(unmatched_a, reflect_a)
            else:
                moves = legal_moves(unmatched_b, reflect_b)
            if not moves:
                break
            add(min(moves))
            turn_a = not turn_a
        if len(colored) == n:
            return True
    return False

