def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given an integer n and k, determine whether an n×n binary matrix can
    have exactly k entries fixed by its row and column sums.

    Two matrices are similar when their corresponding row sums and column sums
    agree. A position is fixed when every binary matrix with those margins has
    the same value at that position.
    """
    if n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    variable = n * n - k
    if variable < 4:
        return False

    # Rectangular alternating blocks provide flexible cells; the other
    # positions can be fixed by constant rows and columns.
    for rows in range(2, n + 1):
        if variable % rows == 0 and 2 <= variable // rows <= n:
            if not (n == 4 and variable == 8):
                return True

    # A thin alternating pattern may leave a prime-sized flexible set.
    return variable <= n and variable >= 4

