MOD = 998244353


def _mat_mul(a, b):
    size = len(a)
    out = [[0] * size for _ in range(size)]
    for i, row in enumerate(a):
        for k, x in enumerate(row):
            if x:
                brow = b[k]
                for j, y in enumerate(brow):
                    if y:
                        out[i][j] = (out[i][j] + x * y) % MOD
    return out


def _mat_vec(a, v):
    return [sum(x * y for x, y in zip(row, v)) % MOD for row in a]


def _sum_falling_geometric(n, m, max_r):
    # Returns T[r] = sum_{k=1..n} (k)_r * m**k.
    q = max_r + 1
    size = 2 * q
    trans = [[0] * size for _ in range(size)]
    for r in range(q):
        trans[r][r] = m % MOD
        if r:
            trans[r][r - 1] = m * r % MOD
        trans[q + r][q + r] = 1
        for c in range(q):
            trans[q + r][c] = trans[r][c]

    state = [0] * size
    state[0] = 1
    power = trans
    exponent = n
    while exponent:
        if exponent & 1:
            state = _mat_vec(power, state)
        exponent >>= 1
        if exponent:
            power = _mat_mul(power, power)
    return state[q:]


def _set_partitions(items):
    if not items:
        yield ()
        return
    first, *rest = items
    for part in _set_partitions(rest):
        yield ((first,),) + part
        for i in range(len(part)):
            yield part[:i] + (part[i] + (first,),) + part[i + 1:]


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    primes = []
    for x in range(2, m + 1):
        if all(x % p for p in primes if p * p <= x):
            primes.append(x)

    max_blocks = len(primes)
    sums = _sum_falling_geometric(n, m, max_blocks)
    inv_m_powers = [1]
    inv_m = pow(m, MOD - 2, MOD)
    for _ in range(max_blocks):
        inv_m_powers.append(inv_m_powers[-1] * inv_m % MOD)

    # For a prime subset, assign each prime's exponent sum to one sequence
    # position. Primes assigned to the same position form a block.
    moments = {}
    for mask in range(1 << max_blocks):
        subset = [i for i in range(max_blocks) if mask >> i & 1]
        for block in _set_partitions(subset):
            coefficient = 1
            for group in block:
                moment = 0
                for value in range(1, m + 1):
                    term = 1
                    for idx in group:
                        p = primes[idx]
                        e = 0
                        while value % p == 0:
                            value //= p
                            e += 1
                        term *= e
                    moment += term
                coefficient = coefficient * moment % MOD
            b = len(block)
            contribution = coefficient * sums[b] % MOD
            contribution = contribution * inv_m_powers[b] % MOD
            moments[mask, block] = contribution

    return sum(moments.values()) % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Given a string s and an integer k, partition s into k substrings such
    that the sum of the letter changes required to make each substring a
    semi-palindrome is minimized.

    A semi-palindrome has length at least 2 and admits a positive proper
    divisor d of its length such that every sequence of characters at indices
    congruent modulo d is a palindrome.
    """
    n = len(s)
    inf = n + 1

    # cost[i][j] is the minimum number of edits for s[i:j]. For each possible
    # spacing d, compare mirrored positions within each residue class.
    cost = [[inf] * (n + 1) for _ in range(n)]
    for i in range(n):
        for end in range(i + 2, n + 1):
            length = end - i
            best = inf
            for d in range(1, length):
                if length % d:
                    continue
                changes = 0
                for residue in range(d):
                    left = residue
                    right = length - d + residue
                    while left < right:
                        if s[i + left] != s[i + right]:
                            changes += 1
                        left += d
                        right -= d
                if changes < best:
                    best = changes
            cost[i][end] = best

    # dp[p][end]: minimum cost to split the first end characters into p
    # valid pieces, each of length at least two.
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for pieces in range(1, k + 1):
        for end in range(2 * pieces, n + 1):
            for start in range(2 * (pieces - 1), end - 1):
                previous = dp[pieces - 1][start]
                if previous != inf:
                    candidate = previous + cost[start][end]
                    if candidate < dp[pieces][end]:
                        dp[pieces][end] = candidate
    return dp[k][n]

def find_largest_400_number(a: int) -> int:
    """ Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number if and only if:
    1. N has exactly 2 distinct prime factors.
    2. For each prime factor p of N, p divides N an even number of times.
       (i.e., the maximum k such that p^k divides N is even)

    Args:
        a: An integer where 36 <= a <= 10^12

    Returns:
        The largest 400 number not exceeding a
    """
    limit = int(a**0.5)
    while (limit + 1) * (limit + 1) <= a:
        limit += 1
    while limit * limit > a:
        limit -= 1

    # Since every prime exponent in N is even, N is x^2. The required
    # exponent condition then means x has exactly two distinct prime factors.
    smallest_prime = list(range(limit + 1))
    for p in range(2, int(limit**0.5) + 1):
        if smallest_prime[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if smallest_prime[multiple] == multiple:
                    smallest_prime[multiple] = p

    for x in range(limit, 1, -1):
        remaining = x
        factor_count = 0
        while remaining > 1 and factor_count < 3:
            factor = smallest_prime[remaining]
            factor_count += 1
            while remaining % factor == 0:
                remaining //= factor
        if factor_count == 2:
            return x * x

    # The input lower bound guarantees at least 36 = 2^2 * 3^2.
    return 36

