def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings extending the given partially fixed grid."""
    MOD = 998244353

    # Transfer across the shorter side. A row state must itself be a proper
    # coloring; between consecutive rows, corresponding colors must differ.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = []
    for row in grid:
        masks = []
        for ch in row:
            masks.append((1 << (int(ch) - 1)) if ch != "?" else 0b111)
        allowed.append(masks)

    # Enumerate proper states in the first row, obeying its fixed cells.
    states = []

    def initial_dfs(col, prev, path):
        if col == W:
            states.append(tuple(path))
            return
        mask = allowed[0][col]
        for color in range(3):
            if mask & (1 << color) and color != prev:
                path.append(color)
                initial_dfs(col + 1, color, path)
                path.pop()

    initial_dfs(0, -1, [])
    dp = {state: 1 for state in states}

    for r in range(1, H):
        next_dp = {}
        masks = allowed[r]

        # For each prior row, enumerate only horizontally valid next rows that
        # differ vertically and satisfy all fixed cells.
        for above, count in dp.items():
            path = []

            def transition_dfs(col, prev):
                if col == W:
                    state = tuple(path)
                    next_dp[state] = (next_dp.get(state, 0) + count) % MOD
                    return
                mask = masks[col]
                for color in range(3):
                    if color != above[col] and color != prev and mask & (1 << color):
                        path.append(color)
                        transition_dfs(col + 1, color)
                        path.pop()

            transition_dfs(0, -1)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % MOD

