def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = list(map(int, str(n)))
        length = len(digits)
        total = 0

        # Fix the required digit sum. The product can then be tracked modulo it.
        for target_sum in range(1, 9 * length + 1):
            # State is (sum so far, product modulo target_sum, started, tight).
            states = {(0, 1 % target_sum, False, True): 1}
            for limit in digits:
                next_states = {}
                for (digit_sum, remainder, started, tight), ways in states.items():
                    upper = limit if tight else 9
                    for digit in range(upper + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target_sum:
                            continue
                        new_tight = tight and digit == limit
                        if not started and digit == 0:
                            key = (new_sum, remainder, False, new_tight)
                        else:
                            new_remainder = (remainder * digit) % target_sum
                            key = (new_sum, new_remainder, True, new_tight)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states

            total += sum(
                ways
                for (digit_sum, remainder, started, _tight), ways in states.items()
                if started and digit_sum == target_sum and remainder == 0
            )
        return total

    return count_up_to(r) - count_up_to(l - 1)

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3.

    The number of sequences with product n is the M-fold divisor function
    d_M(n) = product_{p^e || n} C(M+e-1,e).  The implementation uses a
    segmented factorization so its memory use stays bounded independently of N.
    """
    if N < 1 or M < 1:
        return 0

    # The condition is local at each prime: sigma(p^e) is 0 modulo 3 for
    # p == 2 (mod 3), e odd, or p == 1 (mod 3), e == 2 (mod 3).
    # Accumulate the complementary set, where all local factors are nonzero.
    import math

    limit = math.isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    # Precompute the weights by total prime-factor multiplicity.
    max_omega = N.bit_length() - 1
    weights = [1] * (max_omega + 1)
    for k in range(1, max_omega + 1):
        weights[k] = weights[k - 1] * (M + k - 1) % MOD * pow(k, MOD - 2, MOD) % MOD

    block_size = 1 << 16
    total = 0
    for low in range(1, N + 1, block_size):
        high = min(N + 1, low + block_size)
        length = high - low
        rem = list(range(low, high))
        omega = [0] * length
        bad = bytearray(length)
        for p in primes:
            first = ((low + p - 1) // p) * p
            for v in range(first, high, p):
                idx = v - low
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                if e:
                    omega[idx] += e
                    if p % 3 == 2:
                        if e & 1:
                            bad[idx] = 1
                    elif p % 3 == 1 and e % 3 == 2:
                        bad[idx] = 1
        for idx, r in enumerate(rem):
            n = low + idx
            if n == 1:
                continue
            if r > 1:
                omega[idx] += 1
                if r % 3 == 2:
                    bad[idx] = 1
            if not bad[idx]:
                total += weights[omega[idx]]
        # n=1 is not good, and was deliberately omitted.
    all_sequences = 0
    # The same segmented factorization's complement is being summed above;
    # all sequences are simpler to count by a second multiplicative pass.
    # d_M summatory values are accumulated in the same factorization loop in
    # subsequent versions; here compute them from the standard divisor identity.
    # This direct loop remains bounded-memory and handles the full stated range.
    for low in range(1, N + 1, block_size):
        high = min(N + 1, low + block_size)
        length = high - low
        rem = list(range(low, high))
        omega = [0] * length
        for p in primes:
            first = ((low + p - 1) // p) * p
            for v in range(first, high, p):
                idx = v - low
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    omega[idx] += 1
        for idx, r in enumerate(rem):
            omega[idx] += int(r > 1)
            all_sequences += weights[omega[idx]]
    return (all_sequences - total) % MOD

def sum_concatenated_permutations(n: int) -> int:
    """Sum all concatenated permutations of 1..n modulo 998244353."""
    MOD = 998244353
    ROOT = 3

    def ntt(a, invert):
        size = len(a)
        j = 0
        for i in range(1, size):
            bit = size >> 1
            while j & bit:
                j ^= bit
                bit >>= 1
            j ^= bit
            if i < j:
                a[i], a[j] = a[j], a[i]
        length = 2
        while length <= size:
            wlen = pow(ROOT, (MOD - 1) // length, MOD)
            if invert:
                wlen = pow(wlen, MOD - 2, MOD)
            half = length >> 1
            for start in range(0, size, length):
                w = 1
                for k in range(start, start + half):
                    u, v = a[k], a[k + half] * w % MOD
                    a[k] = (u + v) % MOD
                    a[k + half] = (u - v) % MOD
                    w = w * wlen % MOD
            length <<= 1
        if invert:
            inv_size = pow(size, MOD - 2, MOD)
            for i in range(size):
                a[i] = a[i] * inv_size % MOD

    def multiply(a, b):
        needed = len(a) + len(b) - 1
        size = 1
        while size < needed:
            size <<= 1
        fa, fb = a + [0] * (size - len(a)), b + [0] * (size - len(b))
        ntt(fa, False)
        ntt(fb, False)
        for i in range(size):
            fa[i] = fa[i] * fb[i] % MOD
        ntt(fa, True)
        return fa[:needed]

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    groups = {}
    for x in range(1, n + 1):
        d = len(str(x))
        if d not in groups:
            groups[d] = [0, 0]
        groups[d][0] += 1
        groups[d][1] += x
    poly = [1]
    for d, (count, total) in groups.items():
        a = pow(10, d, MOD)
        gp = [0] * (count + 1)
        term = 1
        for j in range(count + 1):
            gp[j] = term
            if j < count:
                term = term * (count - j) % MOD
                term = term * fact[j] % MOD * invfact[j + 1] % MOD
                term = term * a % MOD
        poly = multiply(poly, gp)

    answer = 0
    for d, (count, total) in groups.items():
        a = pow(10, d, MOD)
        q = 0
        for k in range(n):
            f_k = poly[k] if k < len(poly) else 0
            q = (f_k - a * q) % MOD
            answer = (answer + total * q * fact[k] * fact[n - k - 1]) % MOD
    return answer

