from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _square_digit_signatures(n: int) -> dict[str, int]:
    """Count square values below 10**n by their n-digit padded multisets."""
    last = isqrt(10 ** n - 1)
    counts: dict[str, int] = {}
    for root in range(last + 1):
        signature = "".join(sorted(str(root * root).zfill(n)))
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Count unique square numbers that can be formed from the digits of s.

    Leading zeroes are allowed in the n-digit representation.
    """
    return _square_digit_signatures(n).get("".join(sorted(s)), 0)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0:
        return False
    tile_list = list(tiles[:n])
    usable = []
    for a, b in tile_list:
        if a <= 0 or b <= 0:
            continue
        orientations = {(a, b), (b, a)}
        placements = []
        for th, tw in orientations:
            if th > h or tw > w:
                continue
            for r in range(h - th + 1):
                for c in range(w - tw + 1):
                    mask = 0
                    row_bits = ((1 << tw) - 1) << c
                    for rr in range(r, r + th):
                        mask |= row_bits << (rr * w)
                    placements.append((r * w + c, mask, r, c, th, tw))
        if placements:
            usable.append((a * b, (a, b), placements))

    full = (1 << (h * w)) - 1
    if sum(area for area, _, _ in usable) < h * w:
        return False

    from functools import lru_cache
    path = []

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            print("WITNESS", path)
            return True
        remaining_area = h * w - occupied.bit_count()
        available_area = sum(
            area for i, (area, _, _) in enumerate(usable) if not (used >> i) & 1
        )
        if available_area < remaining_area:
            return False

        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1

        for i, (_, dims, placements) in sorted(enumerate(usable), key=lambda item: -item[1][0]):
            if (used >> i) & 1:
                continue
            for anchor, mask, r, c, th, tw in placements:
                if anchor == pos and not (mask & occupied):
                    path.append((i, dims, r, c, th, tw))
                    if search(occupied | mask, used | (1 << i)):
                        return True
                    path.pop()
        return False

    return search(0, 0)

