def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are axis-aligned rectangles arranged in alternating horizontal and
    vertical strips. Their adjacency graph is the graph of the tile regions.
    """
    import heapq
    from collections import deque

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_h(i, j):
        return (i - j) % 2 == 0

    def index(x, y, i, j):
        return y - j * K if is_h(i, j) else x - i * K

    sk, tk = index(S_x, S_y, si, sj), index(T_x, T_y, ti, tj)
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    # For modest K, directly walk the finite tile graph. Rectangle boundaries
    # lie on integer coordinates, so one midpoint per unit segment finds every
    # neighboring tile, including the long side of a strip.
    if K <= 200:
        def rectangle(tile):
            i, j, k = tile
            if is_h(i, j):
                return i*K, (i+1)*K, j*K+k, j*K+k+1
            return i*K+k, i*K+k+1, j*K, (j+1)*K

        def locate(x, y):
            i, j = int(x // K), int(y // K)
            return (i, j, int(y-j*K) if is_h(i,j) else int(x-i*K))

        todo = deque([start])
        dist = {start: 0}
        while todo:
            u = todo.popleft()
            if u == target:
                return dist[u]
            x0, x1, y0, y1 = rectangle(u)
            neighbors = set()
            for x, sign, lo, hi, vertical in (
                (x0, -1, y0, y1, True), (x1, 1, y0, y1, True),
                (None, 0, x0, x1, False)
            ):
                if vertical:
                    for q in range(lo, hi):
                        neighbors.add(locate(x + sign*0.25, q + 0.5))
                else:
                    for yy, sgn in ((y0, -1), (y1, 1)):
                        for q in range(lo, hi):
                            neighbors.add(locate(q + 0.5, yy + sgn*0.25))
            for v in neighbors:
                if v != u and v not in dist:
                    dist[v] = dist[u] + 1
                    todo.append(v)
        return 0

    # For huge K, use the endpoint-compressed graph of the K-tile paths.
    span = max(abs(ti-si), abs(tj-sj))
    if span > 300:
        return abs(ti-si) + abs(tj-sj)

    def choices(i, j):
        out = {0, K-1}
        if (i,j) == (si,sj): out.add(sk)
        if (i,j) == (ti,tj): out.add(tk)
        return out

    def edge_index(i, j, side):
        return (0 if side == 'B' else K-1) if is_h(i,j) else (0 if side == 'L' else K-1)

    dist = {start: 0}
    heap = [(0,start)]
    bounds = (min(si,ti)-3, max(si,ti)+3, min(sj,tj)-3, max(sj,tj)+3)
    while heap:
        d, (i,j,k) = heapq.heappop(heap)
        if dist.get((i,j,k)) != d: continue
        if (i,j,k) == target: return d
        for q in choices(i,j):
            if q != k:
                nxt=(i,j,q); nd=d+abs(q-k)
                if nd < dist.get(nxt,10**100):
                    dist[nxt]=nd; heapq.heappush(heap,(nd,nxt))
        for di,dj,side,other in ((-1,0,'L','R'),(1,0,'R','L'),(0,-1,'B','T'),(0,1,'T','B')):
            ni,nj=i+di,j+dj
            if not (bounds[0]<=ni<=bounds[1] and bounds[2]<=nj<=bounds[3]): continue
            if di:
                aset,bset=(choices(i,j),{edge_index(ni,nj,other)}) if is_h(i,j) else ({edge_index(i,j,side)},choices(ni,nj))
            else:
                aset,bset=({edge_index(i,j,side)},choices(ni,nj)) if is_h(i,j) else (choices(i,j),{edge_index(ni,nj,other)})
            if k in aset:
                for q in bset:
                    nxt=(ni,nj,q); nd=d+1
                    if nd < dist.get(nxt,10**100):
                        dist[nxt]=nd; heapq.heappush(heap,(nd,nxt))
    return 0

