def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    if h <= 0 or w <= 0:
        return False
    usable = []
    for a, b in list(tiles[:n]):
        placements = []
        for th, tw in {(a, b), (b, a)}:
            if th <= h and tw <= w:
                for r in range(h - th + 1):
                    for c in range(w - tw + 1):
                        mask = 0
                        bits = ((1 << tw) - 1) << c
                        for rr in range(r, r + th):
                            mask |= bits << (rr * w)
                        placements.append((r * w + c, mask, r, c, th, tw))
        if placements:
            usable.append((a * b, (a, b), placements))
    full = (1 << (h * w)) - 1
    if sum(a for a, _, _ in usable) < h * w:
        return False
    from functools import lru_cache
    path = []

    @lru_cache(None)
    def search(occupied, used):
        if occupied == full:
            raise RuntimeError(repr(path))
        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1
        for i, (_, dims, placements) in sorted(enumerate(usable), key=lambda x: -x[1][0]):
            if used >> i & 1:
                continue
            for anchor, mask, r, c, th, tw in placements:
                if anchor == pos and not (mask & occupied):
                    path.append((i, dims, r, c, th, tw))
                    if search(occupied | mask, used | (1 << i)):
                        return True
                    path.pop()
        return False

    return search(0, 0)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether rectangular tiles can exactly cover an H×W grid.

    Tiles may be rotated, some tiles may remain unused, and each tile must fit
    entirely inside the grid with its sides aligned to grid cells.
    """
    if h <= 0 or w <= 0:
        return False

    usable = []
    for a, b in list(tiles[:n]):
        if a <= 0 or b <= 0:
            continue
        placements = []
        for th, tw in {(a, b), (b, a)}:
            if th > h or tw > w:
                continue
            for r in range(h - th + 1):
                for c in range(w - tw + 1):
                    row_bits = ((1 << tw) - 1) << c
                    mask = 0
                    for rr in range(r, r + th):
                        mask |= row_bits << (rr * w)
                    placements.append((r * w + c, mask))
        if placements:
            usable.append((a * b, placements))

    full = (1 << (h * w)) - 1
    if sum(area for area, _ in usable) < h * w:
        return False

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        remaining_area = h * w - occupied.bit_count()
        available_area = sum(
            area
            for i, (area, _) in enumerate(usable)
            if not (used >> i) & 1
        )
        if available_area < remaining_area:
            return False

        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1

        for i, (_, placements) in sorted(
            enumerate(usable), key=lambda item: -item[1][0]
        ):
            if (used >> i) & 1:
                continue
            for anchor, mask in placements:
                if anchor == pos and not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Matrices are similar when corresponding row sums and column sums agree.
    A cell is fixed if its value is the same in every matrix similar to it.
    """
    if n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    variable = n * n - k
    if variable < 4 or k < n:
        return False
    if variable == 2 * n:
        return False
    return True

