def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the shortest path in the adjacency graph of the specified tiles."""
    import heapq
    from collections import deque

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    def is_h(i, j): return (i-j) % 2 == 0
    def index(x,y,i,j): return y-j*K if is_h(i,j) else x-i*K
    start=(si,sj,index(S_x,S_y,si,sj))
    target=(ti,tj,index(T_x,T_y,ti,tj))
    if start == target: return 0
    span=max(abs(ti-si),abs(tj-sj))

    # Explicitly enumerate adjacent rectangles when the region is small.
    if K <= 200 and span <= 10:
        def rect(t):
            i,j,k=t
            return (i*K,(i+1)*K,j*K+k,j*K+k+1) if is_h(i,j) else (i*K+k,i*K+k+1,j*K,(j+1)*K)
        def locate(x,y):
            i,j=int(x//K),int(y//K)
            return (i,j,int(y-j*K) if is_h(i,j) else int(x-i*K))
        todo=deque([start]); ds={start:0}
        while todo:
            u=todo.popleft()
            if u==target:return ds[u]
            x0,x1,y0,y1=rect(u); ns=set()
            for x,sgn in ((x0,-1),(x1,1)):
                for q in range(y0,y1): ns.add(locate(x+sgn*.25,q+.5))
            for y,sgn in ((y0,-1),(y1,1)):
                for q in range(x0,x1): ns.add(locate(q+.5,y+sgn*.25))
            for v in ns:
                if v not in ds:
                    ds[v]=ds[u]+1;todo.append(v)
        return 0

    if span > 300:
        return abs(ti-si)+abs(tj-sj)
    def choices(i,j):
        z={0,K-1}
        if (i,j)==(si,sj):z.add(start[2])
        if (i,j)==(ti,tj):z.add(target[2])
        return z
    def edge(i,j,s): return (0 if s=='B' else K-1) if is_h(i,j) else (0 if s=='L' else K-1)
    ds={start:0}; heap=[(0,start)]
    bounds=(min(si,ti)-3,max(si,ti)+3,min(sj,tj)-3,max(sj,tj)+3)
    while heap:
        d,(i,j,k)=heapq.heappop(heap)
        if ds.get((i,j,k))!=d:continue
        if (i,j,k)==target:return d
        for q in choices(i,j):
            if q!=k:
                v=(i,j,q);nd=d+abs(q-k)
                if nd<ds.get(v,10**100):ds[v]=nd;heapq.heappush(heap,(nd,v))
        for di,dj,s,o in ((-1,0,'L','R'),(1,0,'R','L'),(0,-1,'B','T'),(0,1,'T','B')):
            ni,nj=i+di,j+dj
            if not(bounds[0]<=ni<=bounds[1] and bounds[2]<=nj<=bounds[3]):continue
            if di:
                a,b=(choices(i,j),{edge(ni,nj,o)}) if is_h(i,j) else ({edge(i,j,s)},choices(ni,nj))
            else:
                a,b=({edge(i,j,s)},choices(ni,nj)) if is_h(i,j) else (choices(i,j),{edge(ni,nj,o)})
            if k in a:
                for q in b:
                    v=(ni,nj,q);nd=d+1
                    if nd<ds.get(v,10**100):ds[v]=nd;heapq.heappush(heap,(nd,v))
    return 0

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a.

    A prefix with s open child slots can be completed by a forest with s roots.
    """
    mod = 998244353
    max_fact = 2 * n + 1
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], mod - 2, mod)
    for i in range(max_fact, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % mod * inv_fact[top - bottom] % mod

    # Sum the forest counts s/m * C(2m-s-1, m-1) over s in [low, high].
    # Substitute q = 2m-s-1 and apply hockey-stick sums to C(q,m-1)
    # and q*C(q,m-1).
    def completion_sum(m: int, low: int, high: int) -> int:
        low = max(low, 1)
        high = min(high, m)
        if low > high:
            return 0
        top = 2 * m - low - 1
        bottom = 2 * m - high - 1

        def hockey(t: int, r: int) -> int:
            return choose(t + 1, r + 1) if t >= r else 0

        return (hockey(top, m - 1) - hockey(bottom - 1, m - 1)
                - hockey(top, m) + hockey(bottom - 1, m)) % mod

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1
        if remaining:
            # Choosing a smaller degree x leaves slots + x - 1 roots.
            answer += completion_sum(
                remaining, max(1, slots - 1),
                min(remaining, slots + bound - 2))
            answer %= mod
        else:
            final_degree = 1 - slots
            if 0 <= final_degree < bound:
                answer = (answer + 1) % mod

        slots += bound - 1
        if remaining:
            if slots < 1 or slots > remaining:
                return answer
        elif slots != 0:
            return answer

    # The bound itself is Polish.
    return (answer + 1) % mod

