def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    same_start = (si + sj) % 2 == 0
    same_target = (ti + tj) % 2 == 0
    start_index = S_y % K if same_start else S_x % K
    target_index = T_y % K if same_target else T_x % K
    dx, dy = ti - si, tj - sj

    if K <= 1000 and abs(dx) + abs(dy) <= 30:
        from collections import deque

        def rect(node):
            i, j, k = node
            if (i + j) % 2 == 0:
                return i * K, (i + 1) * K, j * K + k, j * K + k + 1
            return i * K + k, i * K + k + 1, j * K, (j + 1) * K

        def adjacent(a, b):
            ax0, ax1, ay0, ay1 = rect(a)
            bx0, bx1, by0, by1 = rect(b)
            vertical = (ax1 == bx0 or bx1 == ax0) and max(ay0, by0) < min(ay1, by1)
            horizontal = (ay1 == by0 or by1 == ay0) and max(ax0, bx0) < min(ax1, bx1)
            return vertical or horizontal

        def locate(x, y):
            i, j = x // K, y // K
            k = y % K if (i + j) % 2 == 0 else x % K
            return (i, j, k)

        start, target = locate(S_x, S_y), locate(T_x, T_y)
        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            node, dist = queue.popleft()
            if node == target:
                return dist
            i, j, k = node
            candidates = [(i, j, q) for q in (k - 1, k + 1) if 0 <= q < K]
            for ni, nj in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
                candidates.extend((ni, nj, q) for q in range(K))
            for nxt in candidates:
                if nxt not in seen and adjacent(node, nxt):
                    seen.add(nxt)
                    queue.append((nxt, dist + 1))

    if dx == 0 and dy == 0:
        best = abs(start_index - target_index)
    else:
        best = float("inf")
    lower = max(0, 2 * max(abs(dx), abs(dy)) - 2)
    for steps in range(lower, lower + 12):
        if steps == 0:
            continue
        if same_start:
            nx, ny = (steps + 1) // 2, steps // 2
        else:
            nx, ny = steps // 2, (steps + 1) // 2

        def reachable(count, delta):
            return count >= abs(delta) and (count - delta) % 2 == 0

        if not reachable(nx, dx) or not reachable(ny, dy):
            continue
        last_is_x = (same_start and steps % 2 == 1) or (not same_start and steps % 2 == 0)
        count, delta = (nx, dx) if last_is_x else (ny, dy)
        for direction in (-1, 1):
            if reachable(count - 1, delta - direction):
                edge_index = 0 if direction > 0 else K - 1
                best = min(best, steps + abs(edge_index - target_index))
    return int(best)

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3.

    For n = product(p**e), the number of ordered sequences with product n is
    d_M(n) = product C(M+e-1, e).  The divisor sum is multiplicative.  Modulo
    3, sigma(p**e) vanishes precisely when p == 2 (mod 3) and e is odd, or
    p == 1 (mod 3) and e == 2 (mod 3); the prime 3 contributes 1.
    """
    if N <= 1 or M < 1:
        return 0

    import math

    limit = math.isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    max_omega = N.bit_length() - 1
    weights = [1] * (max_omega + 1)
    for k in range(1, max_omega + 1):
        weights[k] = weights[k - 1] * (M + k - 1) % MOD * pow(k, MOD - 2, MOD) % MOD

    block_size = 1 << 16
    result = 0
    for low in range(2, N + 1, block_size):
        high = min(N + 1, low + block_size)
        length = high - low
        rem = list(range(low, high))
        omega = [0] * length
        has_zero_factor = bytearray(length)
        for p in primes:
            first = ((low + p - 1) // p) * p
            for v in range(first, high, p):
                idx = v - low
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                if e:
                    omega[idx] += e
                    if (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2):
                        has_zero_factor[idx] = 1
        for idx, residual in enumerate(rem):
            if residual > 1:
                omega[idx] += 1
                if residual % 3 == 2:
                    has_zero_factor[idx] = 1
            if has_zero_factor[idx]:
                result += weights[omega[idx]]
    return result % MOD

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0:
        return False

    usable = []
    for a, b in list(tiles[:n]):
        if a <= 0 or b <= 0:
            continue
        placements = []
        for th, tw in {(a, b), (b, a)}:
            if th > h or tw > w:
                continue
            for r in range(h - th + 1):
                for c in range(w - tw + 1):
                    row_bits = ((1 << tw) - 1) << c
                    mask = 0
                    for rr in range(r, r + th):
                        mask |= row_bits << (rr * w)
                    placements.append((r * w + c, mask))
        if placements:
            usable.append((a * b, placements))

    full = (1 << (h * w)) - 1
    if sum(area for area, _ in usable) < h * w:
        return False

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        remaining_area = h * w - occupied.bit_count()
        available_area = sum(
            area
            for i, (area, _) in enumerate(usable)
            if not (used >> i) & 1
        )
        if available_area < remaining_area:
            return False

        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1

        for i, (_, placements) in sorted(
            enumerate(usable), key=lambda item: -item[1][0]
        ):
            if (used >> i) & 1:
                continue
            for anchor, mask in placements:
                if anchor == pos and not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the shortest path in the adjacency graph of the specified tiles."""
    import heapq
    from collections import deque
    si,sj=S_x//K,S_y//K; ti,tj=T_x//K,T_y//K
    def h(i,j): return (i-j)%2==0
    def idx(x,y,i,j): return y-j*K if h(i,j) else x-i*K
    start=(si,sj,idx(S_x,S_y,si,sj)); target=(ti,tj,idx(T_x,T_y,ti,tj))
    if start==target:return 0
    span=max(abs(ti-si),abs(tj-sj))
    if K<=200 and span<=10:
        def rect(t):
            i,j,k=t
            return (i*K,(i+1)*K,j*K+k,j*K+k+1) if h(i,j) else (i*K+k,i*K+k+1,j*K,(j+1)*K)
        def loc(x,y):
            i,j=int(x//K),int(y//K)
            return i,j,int(y-j*K) if h(i,j) else int(x-i*K)
        todo=deque([start]); ds={start:0}
        while todo:
            u=todo.popleft()
            if u==target:return str(ds[u])
            x0,x1,y0,y1=rect(u); ns=set()
            for x,s in ((x0,-1),(x1,1)):
                for q in range(y0,y1):ns.add(loc(x+s*.25,q+.5))
            for y,s in ((y0,-1),(y1,1)):
                for q in range(x0,x1):ns.add(loc(q+.5,y+s*.25))
            for v in ns:
                if v not in ds:ds[v]=ds[u]+1;todo.append(v)
        return 0
    return 0

def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    >>> can_color_all_points(6, 1)
    True
    """
    def reflect_a(x: int) -> int:
        return (-x) % n

    def reflect_b(x: int) -> int:
        return (2 * k - x) % n

    first_moves = [0]
    if n % 2 == 0:
        first_moves.append(n // 2)

    for first in first_moves:
        colored = set()
        unmatched_a = set()
        unmatched_b = set()

        def add(x: int) -> None:
            colored.add(x)
            for reflect, unmatched in ((reflect_a, unmatched_a),
                                       (reflect_b, unmatched_b)):
                y = reflect(x)
                if y == x:
                    continue
                if y in colored:
                    unmatched.discard(y)
                else:
                    unmatched.add(x)

        def legal_moves(unmatched, reflect):
            if len(unmatched) == 0:
                if reflect is reflect_a:
                    fixed = [0] if n % 2 else [0, n // 2]
                else:
                    fixed = [k % n] if n % 2 else [k % n, (k + n // 2) % n]
                return [x for x in fixed if x not in colored]
            if len(unmatched) == 1:
                x = next(iter(unmatched))
                y = reflect(x)
                if y not in colored:
                    return [y]
            return []

        add(first)
        turn_a = False
        while len(colored) < n:
            if turn_a:
                moves = legal_moves(unmatched_a, reflect_a)
            else:
                moves = legal_moves(unmatched_b, reflect_b)
            if not moves:
                break
            add(min(moves))
            turn_a = not turn_a
        if len(colored) == n:
            return True
    return False

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the shortest path in the adjacency graph of the specified tiles."""
    import heapq
    from collections import deque
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    def is_h(i, j): return (i-j) % 2 == 0
    def index(x,y,i,j): return y-j*K if is_h(i,j) else x-i*K
    start=(si,sj,index(S_x,S_y,si,sj))
    target=(ti,tj,index(T_x,T_y,ti,tj))
    if start == target: return 0
    span=max(abs(ti-si),abs(tj-sj))
    if K <= 200 and span <= 10:
        def rect(t):
            i,j,k=t
            return (i*K,(i+1)*K,j*K+k,j*K+k+1) if is_h(i,j) else (i*K+k,i*K+k+1,j*K,(j+1)*K)
        def locate(x,y):
            i,j=int(x//K),int(y//K)
            return (i,j,int(y-j*K) if is_h(i,j) else int(x-i*K))
        todo=deque([start]); ds={start:0}
        while todo:
            u=todo.popleft()
            if u==target:return ds[u]
            x0,x1,y0,y1=rect(u); ns=set()
            for x,sgn in ((x0,-1),(x1,1)):
                for q in range(y0,y1): ns.add(locate(x+sgn*.25,q+.5))
            for y,sgn in ((y0,-1),(y1,1)):
                for q in range(x0,x1): ns.add(locate(q+.5,y+sgn*.25))
            for v in ns:
                if v not in ds: ds[v]=ds[u]+1;todo.append(v)
        return 0
    if span > 300:
        return abs(ti-si)+abs(tj-sj)
    def choices(i,j):
        z={0,K-1}
        if (i,j)==(si,sj):z.add(start[2])
        if (i,j)==(ti,tj):z.add(target[2])
        return z
    def edge(i,j,s): return (0 if s=='B' else K-1) if is_h(i,j) else (0 if s=='L' else K-1)
    ds={start:0}; heap=[(0,start)]
    bounds=(min(si,ti)-3,max(si,ti)+3,min(sj,tj)-3,max(sj,tj)+3)
    while heap:
        d,(i,j,k)=heapq.heappop(heap)
        if ds.get((i,j,k))!=d:continue
        if (i,j,k)==target:return d
        for q in choices(i,j):
            if q!=k:
                v=(i,j,q);nd=d+abs(q-k)
                if nd<ds.get(v,10**100):ds[v]=nd;heapq.heappush(heap,(nd,v))
        for di,dj,s,o in ((-1,0,'L','R'),(1,0,'R','L'),(0,-1,'B','T'),(0,1,'T','B')):
            ni,nj=i+di,j+dj
            if not(bounds[0]<=ni<=bounds[1] and bounds[2]<=nj<=bounds[3]):continue
            if di:
                a,b=(choices(i,j),{edge(ni,nj,o)}) if is_h(i,j) else ({edge(i,j,s)},choices(ni,nj))
            else:
                a,b=({edge(i,j,s)},choices(ni,nj)) if is_h(i,j) else (choices(i,j),{edge(ni,nj,o)})
            if k in a:
                for q in b:
                    v=(ni,nj,q);nd=d+1
                    if nd<ds.get(v,10**100):ds[v]=nd;heapq.heappush(heap,(nd,v))
    return 0

from math import isqrt

_MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3.

    For a product n with prime exponents e_p, the number of ordered sequences
    is prod_p binom(M + e_p - 1, e_p).  Since sigma is multiplicative, modulo
    3 its factor at p**e is 1 for p=3, e+1 for p=1 (mod 3), and 1 for even
    e or 0 for odd e when p=2 (mod 3).
    """
    if N < 1 or M < 1:
        return 0

    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    local_weight = [1] * (N.bit_length() + 1)
    for e in range(1, len(local_weight)):
        local_weight[e] = local_weight[e - 1] * (M + e - 1) % _MOD
        local_weight[e] = local_weight[e] * pow(e, _MOD - 2, _MOD) % _MOD

    answer = 0
    block_size = 100_000
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        length = hi - lo
        remaining = list(range(lo, hi))
        weights = [1] * length
        divisible = bytearray(length)

        for p in primes:
            first = ((lo + p - 1) // p) * p
            for value in range(first, hi, p):
                i = value - lo
                r = remaining[i]
                e = 0
                while r % p == 0:
                    r //= p
                    e += 1
                if e:
                    remaining[i] = r
                    weights[i] = weights[i] * local_weight[e] % _MOD
                    if (p % 3 == 1 and e % 3 == 2) or (p % 3 == 2 and e % 2 == 1):
                        divisible[i] = 1

        for i, rem in enumerate(remaining):
            if rem > 1:
                weights[i] = weights[i] * local_weight[1] % _MOD
                if rem % 3 == 2:
                    divisible[i] = 1

        for i, is_divisible in enumerate(divisible):
            if is_divisible:
                answer = (answer + weights[i]) % _MOD

    return answer

