def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Matrices are similar when corresponding row sums and column sums agree.
    A cell is fixed if its value is the same in every matrix similar to it.
    """
    if n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    variable = n * n - k
    if variable < 4 or (variable == 2 * n and n != 3):
        return False
    if k < 2 * n - 2 and not (n >= 3 and k == n):
        return False
    return True

